import { useAuth } from "@/_core/hooks/useAuth";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from "@/components/ui/alert-dialog";
import { EmployeeForm, type EditableEmployee, type EmployeeFormValues } from "@/components/EmployeeForm";
import { BranchForm } from "@/components/BranchForm";
import { ArchiveEmployeeDialog } from "@/components/ArchiveEmployeeDialog";
import { trpc } from "@/lib/trpc";
import { getSaveFailureMessage } from "@/lib/save-feedback";
import React, { useEffect, useMemo, useState } from "react";
import { toast } from "sonner";
import { Archive, CalendarCheck2, CheckCircle2, ClipboardList, Clock3, FileBarChart2, HandCoins, Pencil, Plus, ReceiptText, UsersRound } from "lucide-react";

type Module = "employees" | "attendance" | "shifts" | "leaves" | "kpis" | "payroll";

const content: Record<Module, { eyebrow: string; title: string; description: string; action: string; icon: typeof UsersRound }> = {
  employees: { eyebrow: "فريق الصيدلية", title: "ملفات الموظفين", description: "أنشئ ملفات الفريق واربط كل موظف بالفرع والدور الوظيفي المناسب.", action: "إضافة موظف", icon: UsersRound },
  attendance: { eyebrow: "سجل اليوم", title: "الحضور والانصراف", description: "سجّل وقت الدخول والخروج واحسب ساعات العمل والتأخير تلقائياً.", action: "تسجيل حضور", icon: Clock3 },
  shifts: { eyebrow: "تخطيط التشغيل", title: "جدول الورديات", description: "أنشئ ورديات الفرع واعرض جدولك القادم في مساحة واحدة.", action: "إنشاء وردية", icon: CalendarCheck2 },
  leaves: { eyebrow: "إدارة الاستحقاقات", title: "طلبات الإجازات", description: "قدّم طلبات الإجازة وتابع الأرصدة والقرارات المسجلة عليها.", action: "طلب إجازة", icon: ClipboardList },
  kpis: { eyebrow: "قياس الأداء", title: "مؤشرات الأداء", description: "اربط أداء الفريق بأهداف مبيعات وخدمة والتزام قابلة للقياس.", action: "إضافة مؤشر", icon: FileBarChart2 },
  payroll: { eyebrow: "الاستحقاقات المالية", title: "الرواتب الشهرية", description: "أنشئ مسير رواتب يحسب الخصومات والمكافآت من سجلات الحضور والأداء.", action: "إنشاء مسير", icon: HandCoins },
};

const fieldClass = "mt-1 h-10 rounded-xl border-[#d7e6df] bg-white text-[#17344a] focus-visible:ring-[#0f766e]";
const selectClass = "mt-1 h-10 w-full rounded-xl border border-[#d7e6df] bg-white px-3 text-sm text-[#17344a] outline-none focus:ring-2 focus:ring-[#0f766e]";

function isManagerRole(role?: string) {
  return role === "admin" || role === "owner" || role === "manager";
}

function isPayrollRole(role?: string) {
  return isManagerRole(role) || role === "hr_manager";
}

function isOwnerRole(role?: string) {
  return role === "admin" || role === "owner";
}

function toInputDate(value: Date) {
  return value.toISOString().slice(0, 10);
}

function formatDate(value?: Date | null) {
  return value ? new Intl.DateTimeFormat("ar-EG", { year: "numeric", month: "short", day: "numeric" }).format(new Date(value)) : "—";
}

function formatTime(value?: Date | null) {
  return value ? new Intl.DateTimeFormat("ar-EG", { hour: "2-digit", minute: "2-digit" }).format(new Date(value)) : "—";
}

export function getAttendanceProfileGuard(employee: unknown) {
  return employee ? { canLoadAttendance: true, message: null } : { canLoadAttendance: false, message: "لا يوجد ملف موظف مرتبط بحسابك" };
}

function Header({ module, action, onAction, actionVisible = true }: { module: Module; action?: string; onAction?: () => void; actionVisible?: boolean }) {
  const item = content[module];
  return <section className="flex flex-col gap-5 rounded-[1.75rem] border border-[#dce9e2] bg-white p-6 shadow-[0_18px_42px_-34px_rgba(23,52,74,.45)] sm:flex-row sm:items-end sm:justify-between"><div className="max-w-2xl"><Badge className="border-0 bg-[#e6f5ef] text-[#0f766e] hover:bg-[#e6f5ef]">{item.eyebrow}</Badge><h2 className="mt-3 text-2xl font-extrabold tracking-tight text-[#17344a]">{item.title}</h2><p className="mt-2 text-sm leading-7 text-slate-500">{item.description}</p></div>{actionVisible && action && onAction ? <Button onClick={onAction} className="h-11 shrink-0 rounded-xl bg-[#0f766e] px-5 font-bold hover:bg-[#0b5c56]"><Plus className="ml-2 h-4 w-4" />{action}</Button> : null}</section>;
}

function EmptyState({ icon: Icon, title, description }: { icon: typeof UsersRound; title: string; description: string }) {
  return <Card className="border-[#e1ece6] bg-white"><CardContent className="grid min-h-52 place-items-center p-6"><div className="max-w-md text-center"><span className="mx-auto grid h-14 w-14 place-items-center rounded-3xl bg-[#e6f5ef] text-[#0f766e]"><Icon className="h-6 w-6" /></span><h3 className="mt-4 text-base font-extrabold text-[#17344a]">{title}</h3><p className="mt-2 text-sm leading-6 text-slate-500">{description}</p></div></CardContent></Card>;
}

function FormCard({ title, children }: { title: string; children: React.ReactNode }) {
  return <Card className="border-[#cce3d8] bg-[#f8fcfa]"><CardContent className="p-5"><h3 className="text-sm font-extrabold text-[#17344a]">{title}</h3><div className="mt-4">{children}</div></CardContent></Card>;
}

function BranchSelector({ branches, value, onChange }: { branches: Array<{ id: number; name: string }>; value: number; onChange: (value: number) => void }) {
  if (branches.length <= 1) return null;
  return <label className="mb-4 block max-w-xs"><span className="text-xs font-bold text-slate-600">الفرع الحالي</span><select value={value || ""} onChange={event => onChange(Number(event.target.value))} className={selectClass}><option value="" disabled>اختر الفرع</option>{branches.map(branch => <option key={branch.id} value={branch.id}>{branch.name}</option>)}</select></label>;
}

function EmployeesModule({ activeBranchId, setActiveBranchId }: { activeBranchId: number; setActiveBranchId: (value: number) => void }) {
  const { user } = useAuth();
  const manager = isManagerRole(user?.role);
  const owner = isOwnerRole(user?.role);
  const [showEmployeeForm, setShowEmployeeForm] = useState(false);
  const [showBranchForm, setShowBranchForm] = useState(false);
  const [branchFormError, setBranchFormError] = useState<string | null>(null);
  const [employeeFormError, setEmployeeFormError] = useState<string | null>(null);
  const [editingEmployee, setEditingEmployee] = useState<EditableEmployee | null>(null);
  const [employeeToArchive, setEmployeeToArchive] = useState<{ id: number; fullName: string } | null>(null);
  const [employeeToUnlink, setEmployeeToUnlink] = useState<{ id: number; fullName: string } | null>(null);
  const [archiveError, setArchiveError] = useState<string | null>(null);
  const [employeeToLink, setEmployeeToLink] = useState<{ id: number; fullName: string } | null>(null);
  const [selectedUserId, setSelectedUserId] = useState(0);
  const [certificateEmployeeId, setCertificateEmployeeId] = useState<number | null>(null);
  const [employeeSearch, setEmployeeSearch] = useState("");
  const [roleFilter, setRoleFilter] = useState<"manager" | "pharmacist" | "employee" | "all">("all");
  const [statusFilter, setStatusFilter] = useState<"active" | "inactive" | "on_leave">("active");
  const [employeeSortBy, setEmployeeSortBy] = useState<"name" | "hireDate" | "createdAt">("name");
  const [employeeSortDirection, setEmployeeSortDirection] = useState<"asc" | "desc">("asc");
  const branchesQuery = trpc.organization.listBranches.useQuery();
  const employeeListInput = useMemo(() => activeBranchId ? {
    branchId: activeBranchId,
    search: employeeSearch.trim() || undefined,
    role: roleFilter === "all" ? undefined : roleFilter,
    status: statusFilter,
    sortBy: employeeSortBy,
    sortDirection: employeeSortDirection,
  } : undefined, [activeBranchId, employeeSearch, roleFilter, statusFilter, employeeSortBy, employeeSortDirection]);
  const employeesQuery = trpc.employees.list.useQuery(employeeListInput, { enabled: manager && Boolean(activeBranchId) });
  const unlinkedUsersQuery = trpc.profile.unlinkedUsers.useQuery(undefined, { enabled: owner });
  const pendingLinkRequestsQuery = trpc.employees.pendingLinkRequests.useQuery(undefined, { enabled: owner });
  const linkHistoryQuery = trpc.employees.linkHistory.useQuery(undefined, { enabled: manager });
  const employeeSaveError = (error: unknown) => { const message = getSaveFailureMessage(error, "تعذر حفظ بيانات الموظف. حاول مجدداً."); setEmployeeFormError(message); toast.error(message); };
  const createEmployee = trpc.employees.create.useMutation({ onSuccess: () => { toast.success("تمت إضافة ملف الموظف."); setEmployeeFormError(null); setShowEmployeeForm(false); employeesQuery.refetch(); }, onError: employeeSaveError });
  const updateEmployee = trpc.employees.update.useMutation({ onSuccess: () => { toast.success("تم حفظ تعديلات الموظف."); setEmployeeFormError(null); setEditingEmployee(null); setShowEmployeeForm(false); employeesQuery.refetch(); }, onError: employeeSaveError });
  const archiveEmployee = trpc.employees.archive.useMutation({ onSuccess: () => { toast.success("تمت أرشفة ملف الموظف مع الاحتفاظ بسجله."); setArchiveError(null); setEmployeeToArchive(null); employeesQuery.refetch(); }, onError: error => { const message = getSaveFailureMessage(error, "تعذرت أرشفة الموظف. حاول مجدداً."); setArchiveError(message); toast.error(message); } });
  const refreshLinking = async () => { await Promise.all([employeesQuery.refetch(), unlinkedUsersQuery.refetch(), pendingLinkRequestsQuery.refetch(), linkHistoryQuery.refetch()]); };
  const linkUser = trpc.employees.linkUser.useMutation({ onSuccess: async result => { await refreshLinking(); toast.success(result.existing ? "الحساب مرتبط بالفعل بهذا الملف." : "تم ربط الحساب بملف الموظف بنجاح وأُرسل إشعار داخلي للموظف."); setEmployeeToLink(null); setSelectedUserId(0); }, onError: error => toast.error(error.message) });
  const requestUserLink = trpc.employees.requestUserLink.useMutation({ onSuccess: async result => { await refreshLinking(); toast.success(result.existing ? "يوجد طلب ربط مماثل بانتظار اعتماد المالك." : "تم إرسال طلب الربط إلى المالك لاعتماده."); setEmployeeToLink(null); setSelectedUserId(0); }, onError: error => toast.error(error.message) });
  const unlinkUser = trpc.employees.unlinkUser.useMutation({ onSuccess: async () => { await refreshLinking(); toast.success("تم فك ربط الحساب وإضافة العملية إلى السجل."); setEmployeeToUnlink(null); }, onError: error => toast.error(error.message) });
  const reviewLinkRequest = trpc.employees.reviewLinkRequest.useMutation({ onSuccess: async result => { await refreshLinking(); toast.success(result.status === "approved" ? "تم اعتماد الطلب وربط الحساب وإشعار الموظف." : "تم رفض طلب الربط."); }, onError: error => toast.error(error.message) });
  const createBranch = trpc.organization.createBranch.useMutation({
    onSuccess: async (_result, variables) => {
      const refreshedBranches = await branchesQuery.refetch();
      const createdBranch = refreshedBranches.data?.find(branch => branch.code === variables.code.trim().toUpperCase());
      if (createdBranch) setActiveBranchId(createdBranch.id);
      setBranchFormError(null);
      toast.success(createdBranch ? (_result.existing ? "الفرع موجود مسبقاً وتم اختياره. يمكنك الآن إنشاء ملف الموظف." : "تمت إضافة الفرع واختياره. يمكنك الآن إنشاء ملف الموظف.") : "تمت معالجة الفرع بنجاح.");
      setShowBranchForm(false);
      setShowEmployeeForm(true);
    },
    onError: error => {
      const message = getSaveFailureMessage(error, "تعذر حفظ الفرع. حاول مجدداً.");
      setBranchFormError(message);
      toast.error(message);
    },
  });
  const certificatesQuery = trpc.certificates.listForEmployee.useQuery({ employeeId: certificateEmployeeId ?? 0 }, { enabled: Boolean(certificateEmployeeId) });
  const createCertificate = trpc.certificates.create.useMutation({ onSuccess: () => { toast.success("تمت إضافة الشهادة إلى ملف الموظف."); certificatesQuery.refetch(); }, onError: error => toast.error(error.message) });

  if (!manager) return <><Header module="employees" actionVisible={false} /><EmptyState icon={UsersRound} title="ملفات الفريق مخصصة للإدارة" description="لا تملك صلاحية عرض ملفات الموظفين. ستظهر لك بياناتك الشخصية في بوابتك عند ربط الحساب بملف الموظف." /></>;

  const saveEmployee = (values: EmployeeFormValues) => { if (!activeBranchId) { const message = "أضف فرعاً أو اختر فرعاً أولاً."; setEmployeeFormError(message); return toast.error(message); } setEmployeeFormError(null); if (editingEmployee) return updateEmployee.mutate({ employeeId: editingEmployee.id, ...values }); createEmployee.mutate({ branchId: activeBranchId, ...values }); };
  const openEditEmployee = (employee: EditableEmployee) => { setEditingEmployee(employee); setEmployeeFormError(null); setShowEmployeeForm(true); };
  return <div className="space-y-6"><Header module="employees" action="إضافة موظف" onAction={() => { setEditingEmployee(null); setEmployeeFormError(null); setShowEmployeeForm(true); }} /><BranchSelector branches={branchesQuery.data ?? []} value={activeBranchId} onChange={setActiveBranchId} />{owner ? <button onClick={() => setShowBranchForm(value => !value)} className="text-xs font-bold text-[#0f766e] underline underline-offset-4">{showBranchForm ? "إخفاء نموذج الفرع" : "إضافة فرع جديد"}</button> : null}
    {showBranchForm ? <FormCard title="بيانات الفرع الجديد"><BranchForm error={branchFormError} submitting={createBranch.isPending} onSubmit={values => { setBranchFormError(null); createBranch.mutate(values); }} /></FormCard> : null}
    {showEmployeeForm ? <FormCard title={editingEmployee ? "تعديل ملف الموظف" : "إضافة ملف موظف"}><EmployeeForm employee={editingEmployee} error={employeeFormError} submitting={createEmployee.isPending || updateEmployee.isPending} onSubmit={saveEmployee} onCancel={() => { setEditingEmployee(null); setEmployeeFormError(null); setShowEmployeeForm(false); }} /></FormCard> : null}
    {employeeToLink ? <FormCard title={owner ? `ربط حساب بملف ${employeeToLink.fullName}` : `طلب ربط حساب بملف ${employeeToLink.fullName}`}><div className="flex flex-col gap-3 sm:flex-row sm:items-end"><label className="block w-full max-w-md"><span className="text-xs font-bold text-slate-600">حساب مستخدم غير مرتبط</span><select value={selectedUserId || ""} onChange={event => setSelectedUserId(Number(event.target.value))} className={selectClass}><option value="" disabled>اختر الحساب</option>{(unlinkedUsersQuery.data ?? []).map(account => <option key={account.id} value={account.id}>{account.name || account.email || `حساب #${account.id}`} · {account.role}</option>)}</select></label><Button disabled={!selectedUserId || linkUser.isPending || requestUserLink.isPending} onClick={() => owner ? linkUser.mutate({ employeeId: employeeToLink.id, userId: selectedUserId }) : requestUserLink.mutate({ employeeId: employeeToLink.id, userId: selectedUserId })} className="h-10 rounded-xl bg-[#0f766e] px-5 font-bold hover:bg-[#0b5c56]">{linkUser.isPending || requestUserLink.isPending ? "جارٍ الحفظ..." : owner ? "ربط الحساب" : "إرسال طلب الربط"}</Button><Button type="button" variant="outline" onClick={() => { setEmployeeToLink(null); setSelectedUserId(0); }} className="h-10 border-[#b9d8ca] text-[#0f766e] hover:bg-[#eaf4ef] hover:text-[#0f766e]">إلغاء</Button></div>{!owner ? <p className="mt-3 text-xs leading-5 text-slate-500">سيُرسل الطلب إلى مالك النظام، ولن يُربط الحساب إلا بعد الاعتماد.</p> : null}{!(unlinkedUsersQuery.data ?? []).length ? <p className="mt-3 text-xs text-slate-500">لا توجد حسابات غير مرتبطة حالياً. يدخل الموظف بحسابه أولاً ليظهر هنا.</p> : null}</FormCard> : null}
    {owner && (pendingLinkRequestsQuery.data ?? []).length ? <FormCard title="طلبات ربط الحسابات بانتظار الاعتماد"><div className="divide-y divide-[#e4eee8]">{pendingLinkRequestsQuery.data?.map(item => <div key={item.request.id} className="flex flex-col gap-3 py-3 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-sm font-extrabold text-[#17344a]">{item.employeeName} <span className="font-medium text-slate-400">←</span> {item.accountName || item.accountEmail || `حساب #${item.request.userId}`}</p><p className="mt-1 text-xs text-slate-500">طلبه {item.request.requestedByName || `مستخدم #${item.request.requestedByUserId}`} · {formatDate(item.request.createdAt)}</p></div><div className="flex gap-2"><Button size="sm" disabled={reviewLinkRequest.isPending} onClick={() => reviewLinkRequest.mutate({ requestId: item.request.id, decision: "approved" })} className="bg-[#0f766e] hover:bg-[#0b5c56]">اعتماد وربط</Button><Button size="sm" variant="outline" disabled={reviewLinkRequest.isPending} onClick={() => reviewLinkRequest.mutate({ requestId: item.request.id, decision: "rejected" })} className="border-red-200 text-red-700 hover:bg-red-50 hover:text-red-700">رفض</Button></div></div>)}</div></FormCard> : null}
    {(linkHistoryQuery.data ?? []).length ? <Card className="border-[#dbe9e2] bg-[#f8fcfa]"><CardContent className="p-5"><div className="flex items-center justify-between gap-3"><div><p className="text-sm font-extrabold text-[#17344a]">سجل ربط الحسابات</p><p className="mt-1 text-xs text-slate-500">آخر عمليات الربط وفك الربط ضمن نطاقك الإداري.</p></div><Badge className="border-0 bg-[#e6f5ef] text-[#0f766e] hover:bg-[#e6f5ef]">{linkHistoryQuery.data?.length} عملية</Badge></div><div className="mt-4 divide-y divide-[#e4eee8]">{linkHistoryQuery.data?.slice(0, 5).map(item => <div key={item.log.id} className="flex items-center justify-between gap-3 py-3 text-sm"><div><p className="font-bold text-[#17344a]">{item.log.action === "linked" ? "تم ربط حساب" : "تم فك ربط حساب"} · {item.employeeName}</p><p className="mt-1 text-xs text-slate-500">بواسطة {item.log.actorName || "النظام"} · {formatDate(item.log.createdAt)}</p></div><Badge className={item.log.action === "linked" ? "bg-[#e6f5ef] text-[#0f766e] hover:bg-[#e6f5ef]" : "bg-[#fff1f1] text-[#b42318] hover:bg-[#fff1f1]"}>{item.log.action === "linked" ? "ربط" : "فك ربط"}</Badge></div>)}</div></CardContent></Card> : null}
    {certificateEmployeeId ? <FormCard title="إضافة أو مراجعة شهادة"><form onSubmit={event => { event.preventDefault(); const data = new FormData(event.currentTarget); createCertificate.mutate({ employeeId: certificateEmployeeId, title: String(data.get("title")), issuer: String(data.get("issuer") || "") || undefined, issuedOn: data.get("issuedOn") ? new Date(String(data.get("issuedOn"))) : undefined, expiresOn: data.get("expiresOn") ? new Date(String(data.get("expiresOn"))) : undefined, documentUrl: String(data.get("documentUrl") || "") || undefined }); }} className="grid gap-3 md:grid-cols-4"><label><span className="text-xs font-bold">اسم الشهادة</span><Input name="title" required placeholder="ترخيص مزاولة المهنة" className={fieldClass} /></label><label><span className="text-xs font-bold">الجهة المانحة</span><Input name="issuer" className={fieldClass} /></label><label><span className="text-xs font-bold">تاريخ الإصدار</span><Input name="issuedOn" type="date" className={fieldClass} /></label><label><span className="text-xs font-bold">تاريخ الانتهاء</span><Input name="expiresOn" type="date" className={fieldClass} /></label><label className="md:col-span-3"><span className="text-xs font-bold">رابط الوثيقة (اختياري)</span><Input name="documentUrl" type="url" placeholder="https://…" className={fieldClass} /></label><div className="flex items-end gap-2"><Button disabled={createCertificate.isPending}>{createCertificate.isPending ? "جارٍ الحفظ..." : "حفظ الشهادة"}</Button><Button type="button" variant="outline" onClick={() => setCertificateEmployeeId(null)}>إغلاق</Button></div></form>{(certificatesQuery.data ?? []).length ? <div className="mt-4 divide-y divide-[#e4eee8]">{certificatesQuery.data?.map(certificate => <div key={certificate.id} className="flex items-center justify-between gap-3 py-3 text-sm"><div><p className="font-bold text-[#17344a]">{certificate.title}</p><p className="mt-1 text-xs text-slate-500">{certificate.issuer || "جهة غير محددة"} · ينتهي: {formatDate(certificate.expiresOn)}</p></div>{certificate.documentUrl ? <a className="text-xs font-bold text-[#0f766e] underline" href={certificate.documentUrl} target="_blank" rel="noreferrer">فتح الوثيقة</a> : null}</div>)}</div> : null}</FormCard> : null}
    <Card className="border-[#e1ece6] bg-white"><CardContent className="grid gap-4 p-5 md:grid-cols-2 xl:grid-cols-5"><label className="xl:col-span-2"><span className="text-xs font-bold text-slate-600">بحث</span><Input value={employeeSearch} onChange={event => setEmployeeSearch(event.target.value)} placeholder="الاسم، الكود، الوظيفة، البريد أو الهاتف" className={fieldClass} /></label><label><span className="text-xs font-bold text-slate-600">الدور</span><select value={roleFilter} onChange={event => setRoleFilter(event.target.value as typeof roleFilter)} className={selectClass}><option value="all">كل الأدوار</option><option value="manager">مدير</option><option value="pharmacist">صيدلاني</option><option value="employee">موظف</option></select></label><label><span className="text-xs font-bold text-slate-600">الحالة</span><select value={statusFilter} onChange={event => setStatusFilter(event.target.value as typeof statusFilter)} className={selectClass}><option value="active">نشط</option><option value="on_leave">في إجازة</option><option value="inactive">غير نشط / مؤرشف</option></select></label><label><span className="text-xs font-bold text-slate-600">الفرز</span><div className="mt-1 flex gap-2"><select value={employeeSortBy} onChange={event => setEmployeeSortBy(event.target.value as typeof employeeSortBy)} className="h-10 min-w-0 flex-1 rounded-xl border border-[#d7e6df] bg-white px-2 text-sm outline-none focus:ring-2 focus:ring-[#0f766e]"><option value="name">الاسم</option><option value="hireDate">تاريخ التعيين</option><option value="createdAt">تاريخ الإنشاء</option></select><Button type="button" variant="outline" onClick={() => setEmployeeSortDirection(value => value === "asc" ? "desc" : "asc")} className="h-10 shrink-0 border-[#b9d8ca] px-3 text-xs font-bold text-[#0f766e] hover:bg-[#eaf4ef] hover:text-[#0f766e]">{employeeSortDirection === "asc" ? "تصاعدي" : "تنازلي"}</Button></div></label></CardContent></Card>
    {(employeesQuery.data ?? []).length ? <Card className="border-[#e1ece6] bg-white"><CardContent className="divide-y divide-[#edf3ef] p-0">{employeesQuery.data?.map(employee => <div key={employee.id} className="flex flex-wrap items-center justify-between gap-3 p-5"><div><p className="font-extrabold text-[#17344a]">{employee.fullName}</p><p className="mt-1 text-xs text-slate-500">{employee.jobTitle} · {employee.employeeCode}{employee.userId ? " · حساب مرتبط" : " · دون حساب مرتبط"}</p></div><div className="flex flex-wrap items-center gap-2">{!employee.userId ? <Button size="sm" variant="outline" onClick={() => { setEmployeeToLink({ id: employee.id, fullName: employee.fullName }); setSelectedUserId(0); }} className="border-[#b9d8ca] text-[#0f766e] hover:bg-[#eaf4ef] hover:text-[#0f766e]">{owner ? "ربط حساب" : "طلب ربط"}</Button> : null}{owner && employee.userId ? <Button size="sm" variant="outline" onClick={() => setEmployeeToUnlink({ id: employee.id, fullName: employee.fullName })} className="border-amber-200 text-amber-700 hover:bg-amber-50 hover:text-amber-700">فك الربط</Button> : null}<Button size="sm" variant="outline" onClick={() => setCertificateEmployeeId(employee.id)} className="border-[#b9d8ca] text-[#0f766e] hover:bg-[#eaf4ef] hover:text-[#0f766e]">الشهادات</Button><Button size="sm" variant="outline" onClick={() => openEditEmployee(employee)} className="border-[#b9d8ca] text-[#0f766e] hover:bg-[#eaf4ef] hover:text-[#0f766e]"><Pencil className="ml-1 h-3.5 w-3.5" />تعديل</Button><Button size="sm" variant="outline" onClick={() => setEmployeeToArchive({ id: employee.id, fullName: employee.fullName })} className="border-red-200 text-red-700 hover:bg-red-50 hover:text-red-700"><Archive className="ml-1 h-3.5 w-3.5" />أرشفة</Button><Badge className="bg-[#e6f5ef] text-[#0f766e] hover:bg-[#e6f5ef]">{employee.role === "manager" ? "مدير" : employee.role === "pharmacist" ? "صيدلاني" : "موظف"}</Badge></div></div>)}</CardContent></Card> : <EmptyState icon={UsersRound} title={branchesQuery.data?.length ? "لا توجد ملفات موظفين بعد" : "ابدأ بإضافة فرع"} description={branchesQuery.data?.length ? "أضف أول موظف وربطه بالفرع والدور الوظيفي لبدء تنظيم الفريق." : "أضف فرع الصيدلية أولاً حتى يمكن ربط الفريق والورديات به."} />}
    <ArchiveEmployeeDialog employee={employeeToArchive} pending={archiveEmployee.isPending} error={archiveError} onArchive={employeeId => { setArchiveError(null); archiveEmployee.mutate({ employeeId }); }} onClose={() => { setArchiveError(null); setEmployeeToArchive(null); }} />
    <AlertDialog open={Boolean(employeeToUnlink)} onOpenChange={open => { if (!open) setEmployeeToUnlink(null); }}><AlertDialogContent dir="rtl"><AlertDialogHeader><AlertDialogTitle>تأكيد فك ربط الحساب</AlertDialogTitle><AlertDialogDescription>سيُفك ربط حساب الموظف <strong>{employeeToUnlink?.fullName}</strong> وسيُسجّل الإجراء في سجل الربط. لن يتم حذف ملف الموظف.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>إلغاء</AlertDialogCancel><AlertDialogAction disabled={unlinkUser.isPending} onClick={() => employeeToUnlink && unlinkUser.mutate({ employeeId: employeeToUnlink.id })} className="bg-amber-600 hover:bg-amber-700">{unlinkUser.isPending ? "جارٍ فك الربط..." : "فك الربط"}</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>
  </div>;
}

export function AttendanceModule() {
  const { user } = useAuth();
  const profileQuery = trpc.profile.mine.useQuery();
  const branchesQuery = trpc.organization.listBranches.useQuery();
  const [setupBranchId, setSetupBranchId] = useState(0);
  const attendanceGuard = getAttendanceProfileGuard(profileQuery.data?.employee);
  const hasEmployeeProfile = attendanceGuard.canLoadAttendance;
  const canSetUpProfile = isOwnerRole(user?.role);
  useEffect(() => {
    if (!setupBranchId && branchesQuery.data?.[0]) setSetupBranchId(branchesQuery.data[0].id);
  }, [branchesQuery.data, setupBranchId]);
  const attendanceQuery = trpc.attendance.mineToday.useQuery(undefined, { enabled: hasEmployeeProfile });
  const checkIn = trpc.attendance.checkIn.useMutation({ onSuccess: data => { toast.success(data.lateMinutes ? `تم تسجيل الحضور مع تأخير ${data.lateMinutes} دقيقة.` : "تم تسجيل الحضور في الموعد."); attendanceQuery.refetch(); }, onError: error => toast.error(error.message) });
  const checkOut = trpc.attendance.checkOut.useMutation({ onSuccess: data => { toast.success(`تم تسجيل الانصراف. ساعات العمل المسجلة: ${Math.floor(data.workedMinutes / 60)} س ${data.workedMinutes % 60} د.`); attendanceQuery.refetch(); }, onError: error => toast.error(error.message) });
  const setupProfile = trpc.profile.setupEmployeeProfile.useMutation({
    onSuccess: async result => {
      await profileQuery.refetch();
      toast.success(result.existing ? "ملفك الوظيفي مرتبط بالفعل بحسابك." : "تم إنشاء ملفك الوظيفي وربطه بحسابك. يمكنك الآن تسجيل الحضور.");
    },
    onError: error => toast.error(error.message),
  });
  const record = attendanceQuery.data;
  if (profileQuery.isSuccess && !hasEmployeeProfile) {
    return <div className="space-y-6"><Header module="attendance" actionVisible={false} /><Card className="border-[#f2d5d5] bg-white"><CardContent className="p-6"><Badge className="border-0 bg-[#fff1f1] text-[#b42318] hover:bg-[#fff1f1]">يلزم ربط الملف الوظيفي</Badge><h3 className="mt-3 text-lg font-extrabold text-[#17344a]">{attendanceGuard.message}</h3><p className="mt-2 max-w-2xl text-sm leading-7 text-slate-500">الحضور والانصراف وتفاصيل البوابة الشخصية ترتبط بملف الموظف. لن يتم إرسال طلبات حضور حتى يكتمل الربط.</p>{canSetUpProfile ? <div className="mt-5 flex flex-col gap-3 sm:flex-row sm:items-end"><label className="block w-full max-w-sm"><span className="text-xs font-bold text-slate-600">فرع ملفك الوظيفي</span><select value={setupBranchId || ""} onChange={event => setSetupBranchId(Number(event.target.value))} className={selectClass}><option value="" disabled>اختر الفرع</option>{(branchesQuery.data ?? []).map(branch => <option key={branch.id} value={branch.id}>{branch.name}</option>)}</select></label><Button disabled={!setupBranchId || setupProfile.isPending} onClick={() => setupProfile.mutate({ branchId: setupBranchId })} className="h-10 rounded-xl bg-[#0f766e] px-5 font-bold hover:bg-[#0b5c56]">{setupProfile.isPending ? "جارٍ ربط الحساب..." : "إنشاء وربط ملفي الوظيفي"}</Button></div> : <p className="mt-4 text-sm font-bold text-[#b42318]">تواصل مع مالك النظام لربط حسابك بملف موظف قائم.</p>}</CardContent></Card></div>;
  }
  return <div className="space-y-6"><Header module="attendance" actionVisible={false} /><Card className="border-[#e1ece6] bg-white"><CardContent className="p-6"><div className="flex flex-col items-start justify-between gap-5 sm:flex-row sm:items-center"><div><p className="text-sm font-extrabold text-[#17344a]">سجل اليوم</p><p className="mt-1 text-xs text-slate-500">يتم حساب التأخير وساعات العمل آلياً من توقيت التسجيل.</p></div>{record?.checkOutAt ? <Badge className="bg-[#e6f5ef] text-[#0f766e] hover:bg-[#e6f5ef]">اكتملت وردية اليوم</Badge> : record?.checkInAt ? <Badge className="bg-[#fff3db] text-[#b87516] hover:bg-[#fff3db]">في وردية نشطة</Badge> : <Badge className="bg-slate-100 text-slate-600 hover:bg-slate-100">لم يُسجّل حضور</Badge>}</div><div className="mt-6 grid gap-3 sm:grid-cols-3"><div className="rounded-2xl bg-[#f8fbf9] p-4"><p className="text-xs text-slate-500">وقت الحضور</p><p className="mt-2 font-extrabold text-[#17344a]">{formatTime(record?.checkInAt)}</p></div><div className="rounded-2xl bg-[#f8fbf9] p-4"><p className="text-xs text-slate-500">وقت الانصراف</p><p className="mt-2 font-extrabold text-[#17344a]">{formatTime(record?.checkOutAt)}</p></div><div className="rounded-2xl bg-[#f8fbf9] p-4"><p className="text-xs text-slate-500">التأخير</p><p className="mt-2 font-extrabold text-[#17344a]">{record?.lateMinutes ?? 0} دقيقة</p></div></div><div className="mt-6 flex flex-wrap gap-3"><Button disabled={Boolean(record?.checkInAt) || checkIn.isPending} onClick={() => checkIn.mutate()} className="h-11 rounded-xl bg-[#0f766e] px-5 font-bold hover:bg-[#0b5c56]">{checkIn.isPending ? "جارٍ التسجيل..." : "تسجيل الحضور"}</Button><Button variant="outline" disabled={!record?.checkInAt || Boolean(record?.checkOutAt) || checkOut.isPending} onClick={() => checkOut.mutate()} className="h-11 rounded-xl border-[#b9d8ca] px-5 font-bold text-[#0f766e] hover:bg-[#eaf4ef] hover:text-[#0f766e]">{checkOut.isPending ? "جارٍ التسجيل..." : "تسجيل الانصراف"}</Button>{user?.role === "manager" ? <p className="self-center text-xs text-slate-500">يمكنك متابعة سجلات فريقك من لوحة المدير بعد اختيار الفرع.</p> : null}</div></CardContent></Card></div>;
}

function ShiftsModule({ activeBranchId, setActiveBranchId }: { activeBranchId: number; setActiveBranchId: (value: number) => void }) {
  const { user } = useAuth();
  const manager = isManagerRole(user?.role);
  const [showForm, setShowForm] = useState(false);
  const [showAssignmentForm, setShowAssignmentForm] = useState(false);
  const branchesQuery = trpc.organization.listBranches.useQuery();
  const [range] = useState(() => ({ from: new Date(new Date().getFullYear(), new Date().getMonth(), 1), to: new Date(new Date().getFullYear(), new Date().getMonth() + 1, 0) }));
  const myShifts = trpc.shifts.mine.useQuery(range);
  const branchShifts = trpc.shifts.list.useQuery(activeBranchId ? { branchId: activeBranchId } : undefined, { enabled: manager });
  const employeesQuery = trpc.employees.list.useQuery(activeBranchId ? { branchId: activeBranchId } : undefined, { enabled: manager && activeBranchId > 0 });
  const createShift = trpc.shifts.create.useMutation({ onSuccess: () => { toast.success("تم إنشاء الوردية."); setShowForm(false); branchShifts.refetch(); }, onError: error => toast.error(error.message) });
  const assignShift = trpc.shifts.assign.useMutation({ onSuccess: () => { toast.success("تم توزيع الوردية على الموظف."); setShowAssignmentForm(false); myShifts.refetch(); }, onError: error => toast.error(error.message) });
  const visibleShifts = manager ? branchShifts.data?.map(shift => ({ id: shift.id, name: shift.name, startTime: shift.startTime, endTime: shift.endTime, date: null })) : myShifts.data?.map(item => ({ id: item.assignment.id, name: item.shift.name, startTime: item.shift.startTime, endTime: item.shift.endTime, date: item.assignment.workDate }));
  return <div className="space-y-6"><Header module="shifts" action={manager ? "إنشاء وردية" : undefined} onAction={manager ? () => setShowForm(value => !value) : undefined} actionVisible={manager} />{manager ? <><BranchSelector branches={branchesQuery.data ?? []} value={activeBranchId} onChange={setActiveBranchId} /><Button variant="outline" onClick={() => setShowAssignmentForm(value => !value)} className="border-[#b9d8ca] font-bold text-[#0f766e] hover:bg-[#eaf4ef] hover:text-[#0f766e]">توزيع وردية على موظف</Button></> : null}{showForm ? <FormCard title="تعريف وردية جديدة"><form onSubmit={event => { event.preventDefault(); if (!activeBranchId) return toast.error("اختر الفرع أولاً."); const data = new FormData(event.currentTarget); createShift.mutate({ branchId: activeBranchId, name: String(data.get("name")), startTime: String(data.get("startTime")), endTime: String(data.get("endTime")), graceMinutes: Number(data.get("graceMinutes") || 10), breakMinutes: Number(data.get("breakMinutes") || 0), color: "#0F766E" }); }} className="grid gap-3 sm:grid-cols-4"><label><span className="text-xs font-bold">اسم الوردية</span><Input name="name" required placeholder="صباحية" className={fieldClass} /></label><label><span className="text-xs font-bold">من</span><Input name="startTime" type="time" defaultValue="09:00" required className={fieldClass} /></label><label><span className="text-xs font-bold">إلى</span><Input name="endTime" type="time" defaultValue="17:00" required className={fieldClass} /></label><label><span className="text-xs font-bold">سماح التأخير (د)</span><Input name="graceMinutes" type="number" defaultValue="10" min="0" className={fieldClass} /></label><Button disabled={createShift.isPending} className="sm:w-fit">{createShift.isPending ? "جارٍ الحفظ..." : "حفظ الوردية"}</Button></form></FormCard> : null}{showAssignmentForm ? <FormCard title="توزيع وردية"><form onSubmit={event => { event.preventDefault(); const data = new FormData(event.currentTarget); assignShift.mutate({ employeeId: Number(data.get("employeeId")), shiftId: Number(data.get("shiftId")), workDate: new Date(String(data.get("workDate"))), notes: String(data.get("notes") || "") || undefined }); }} className="grid gap-3 sm:grid-cols-4"><label><span className="text-xs font-bold">الموظف</span><select name="employeeId" required className={selectClass}><option value="">اختر الموظف</option>{employeesQuery.data?.map(employee => <option value={employee.id} key={employee.id}>{employee.fullName}</option>)}</select></label><label><span className="text-xs font-bold">الوردية</span><select name="shiftId" required className={selectClass}><option value="">اختر الوردية</option>{branchShifts.data?.map(shift => <option value={shift.id} key={shift.id}>{shift.name} · {String(shift.startTime).slice(0, 5)}</option>)}</select></label><label><span className="text-xs font-bold">تاريخ العمل</span><Input name="workDate" type="date" defaultValue={toInputDate(new Date())} required className={fieldClass} /></label><label><span className="text-xs font-bold">ملاحظة (اختياري)</span><Input name="notes" className={fieldClass} /></label><Button disabled={assignShift.isPending} className="sm:w-fit">{assignShift.isPending ? "جارٍ الحفظ..." : "تأكيد التوزيع"}</Button></form></FormCard> : null}{visibleShifts?.length ? <Card className="border-[#e1ece6] bg-white"><CardContent className="divide-y divide-[#edf3ef] p-0">{visibleShifts.map(shift => <div key={shift.id} className="flex items-center justify-between gap-4 p-5"><div><p className="font-extrabold text-[#17344a]">{shift.name}</p><p className="mt-1 text-xs text-slate-500">{shift.date ? `${formatDate(shift.date)} · ` : ""}{String(shift.startTime).slice(0, 5)} — {String(shift.endTime).slice(0, 5)}</p></div><CalendarCheck2 className="h-5 w-5 text-[#0f766e]" /></div>)}</CardContent></Card> : <EmptyState icon={CalendarCheck2} title="لا توجد ورديات معروضة" description={manager ? "عرّف ورديات الفرع ثم وزّعها على الفريق من وحدة التخطيط." : "ستظهر وردياتك المسندة خلال هذا الشهر هنا."} />}</div>;
}

function LeavesModule({ activeBranchId, setActiveBranchId }: { activeBranchId: number; setActiveBranchId: (value: number) => void }) {
  const { user } = useAuth();
  const manager = isManagerRole(user?.role);
  const [showForm, setShowForm] = useState(false);
  const branchesQuery = trpc.organization.listBranches.useQuery();
  const mine = trpc.leaves.mine.useQuery();
  const pending = trpc.leaves.pending.useQuery({ branchId: activeBranchId }, { enabled: manager && activeBranchId > 0 });
  const submit = trpc.leaves.request.useMutation({ onSuccess: () => { toast.success("تم إرسال طلب الإجازة للمراجعة."); setShowForm(false); mine.refetch(); }, onError: error => toast.error(error.message) });
  const review = trpc.leaves.review.useMutation({ onSuccess: () => { toast.success("تم تحديث قرار الإجازة."); pending.refetch(); mine.refetch(); }, onError: error => toast.error(error.message) });
  return <div className="space-y-6"><Header module="leaves" action="طلب إجازة" onAction={() => setShowForm(value => !value)} />{manager ? <BranchSelector branches={branchesQuery.data ?? []} value={activeBranchId} onChange={setActiveBranchId} /> : null}{showForm ? <FormCard title="طلب إجازة جديد"><form onSubmit={event => { event.preventDefault(); const data = new FormData(event.currentTarget); submit.mutate({ leaveType: String(data.get("leaveType")) as "annual" | "sick" | "emergency" | "unpaid", startDate: new Date(String(data.get("startDate"))), endDate: new Date(String(data.get("endDate"))), totalDays: Number(data.get("totalDays")), reason: String(data.get("reason") || "") || undefined }); }} className="grid gap-3 sm:grid-cols-4"><label><span className="text-xs font-bold">نوع الإجازة</span><select name="leaveType" className={selectClass}><option value="annual">سنوية</option><option value="sick">مرضية</option><option value="emergency">طارئة</option><option value="unpaid">بدون راتب</option></select></label><label><span className="text-xs font-bold">من</span><Input name="startDate" type="date" required defaultValue={toInputDate(new Date())} className={fieldClass} /></label><label><span className="text-xs font-bold">إلى</span><Input name="endDate" type="date" required defaultValue={toInputDate(new Date())} className={fieldClass} /></label><label><span className="text-xs font-bold">عدد الأيام</span><Input name="totalDays" type="number" min="0.5" step="0.5" required className={fieldClass} /></label><label className="sm:col-span-3"><span className="text-xs font-bold">سبب الطلب (اختياري)</span><Input name="reason" className={fieldClass} /></label><div className="flex items-end"><Button disabled={submit.isPending}>{submit.isPending ? "جارٍ الإرسال..." : "إرسال الطلب"}</Button></div></form></FormCard> : null}<section className="grid gap-5 xl:grid-cols-2"><Card className="border-[#e1ece6] bg-white"><CardContent className="p-5"><h3 className="text-sm font-extrabold text-[#17344a]">رصيدك وطلباتك</h3><div className="mt-4 grid gap-3 sm:grid-cols-2">{(mine.data?.balances ?? []).map(balance => <div key={balance.id} className="rounded-2xl bg-[#f8fbf9] p-4 text-sm"><p className="font-bold text-[#17344a]">رصيد {balance.year}</p><p className="mt-2 text-xs text-slate-500">سنوية مستخدمة: {balance.annualUsed} · مرضية مستخدمة: {balance.sickUsed}</p></div>)}</div>{(mine.data?.requests ?? []).length ? <div className="mt-4 divide-y divide-[#edf3ef]">{mine.data?.requests.map(request => <div key={request.id} className="flex items-center justify-between gap-3 py-3"><div><p className="text-sm font-bold text-[#17344a]">{request.leaveType === "annual" ? "إجازة سنوية" : request.leaveType === "sick" ? "إجازة مرضية" : request.leaveType === "emergency" ? "إجازة طارئة" : "إجازة بدون راتب"}</p><p className="mt-1 text-xs text-slate-500">{formatDate(request.startDate)} — {formatDate(request.endDate)} · {request.totalDays} يوم</p></div><Badge className={request.status === "approved" ? "bg-[#e6f5ef] text-[#0f766e] hover:bg-[#e6f5ef]" : request.status === "rejected" ? "bg-rose-50 text-rose-700 hover:bg-rose-50" : "bg-[#fff3db] text-[#b87516] hover:bg-[#fff3db]"}>{request.status === "approved" ? "معتمد" : request.status === "rejected" ? "مرفوض" : "بانتظار المراجعة"}</Badge></div>)}</div> : <p className="mt-5 text-sm text-slate-500">لا توجد طلبات إجازة حتى الآن.</p>}</CardContent></Card>{manager ? <Card className="border-[#e1ece6] bg-white"><CardContent className="p-5"><h3 className="text-sm font-extrabold text-[#17344a]">طلبات تنتظر قرارك</h3>{(pending.data ?? []).length ? <div className="mt-4 divide-y divide-[#edf3ef]">{pending.data?.map(item => <div key={item.request.id} className="py-4"><p className="text-sm font-bold text-[#17344a]">{item.employee.fullName}</p><p className="mt-1 text-xs text-slate-500">{formatDate(item.request.startDate)} — {formatDate(item.request.endDate)} · {item.request.totalDays} يوم</p><div className="mt-3 flex gap-2"><Button size="sm" disabled={review.isPending} onClick={() => review.mutate({ requestId: item.request.id, approve: true })}>اعتماد</Button><Button size="sm" variant="outline" disabled={review.isPending} onClick={() => review.mutate({ requestId: item.request.id, approve: false })} className="border-rose-200 text-rose-700 hover:bg-rose-50 hover:text-rose-700">رفض</Button></div></div>)}</div> : <p className="mt-5 text-sm text-slate-500">لا توجد طلبات معلقة لهذا الفرع.</p>}</CardContent></Card> : null}</section></div>;
}

function KpisModule({ activeBranchId, setActiveBranchId }: { activeBranchId: number; setActiveBranchId: (value: number) => void }) {
  const { user } = useAuth();
  const manager = isManagerRole(user?.role);
  const [showDefinitionForm, setShowDefinitionForm] = useState(false);
  const [showRecordForm, setShowRecordForm] = useState(false);
  const [range] = useState(() => ({ from: new Date(new Date().getFullYear(), new Date().getMonth(), 1), to: new Date(new Date().getFullYear(), new Date().getMonth() + 1, 0) }));
  const branchesQuery = trpc.organization.listBranches.useQuery();
  const definitions = trpc.kpis.definitions.useQuery(activeBranchId ? { branchId: activeBranchId } : undefined);
  const mine = trpc.kpis.mine.useQuery(range);
  const employeesQuery = trpc.employees.list.useQuery(activeBranchId ? { branchId: activeBranchId } : undefined, { enabled: manager && activeBranchId > 0 });
  const createDefinition = trpc.kpis.createDefinition.useMutation({ onSuccess: () => { toast.success("تم إنشاء مؤشر الأداء."); setShowDefinitionForm(false); definitions.refetch(); }, onError: error => toast.error(error.message) });
  const record = trpc.kpis.record.useMutation({ onSuccess: data => { toast.success(`تم تسجيل النتيجة بنسبة إنجاز ${data.score.toFixed(1)}٪.`); setShowRecordForm(false); mine.refetch(); }, onError: error => toast.error(error.message) });
  return <div className="space-y-6"><Header module="kpis" action={manager ? "إضافة مؤشر" : undefined} onAction={manager ? () => setShowDefinitionForm(value => !value) : undefined} actionVisible={manager} />{manager ? <><BranchSelector branches={branchesQuery.data ?? []} value={activeBranchId} onChange={setActiveBranchId} /><div className="flex gap-3"><Button variant="outline" onClick={() => setShowRecordForm(value => !value)} className="border-[#b9d8ca] font-bold text-[#0f766e] hover:bg-[#eaf4ef] hover:text-[#0f766e]">تسجيل نتيجة موظف</Button></div></> : null}{showDefinitionForm ? <FormCard title="تعريف مؤشر أداء"><form onSubmit={event => { event.preventDefault(); if (!activeBranchId) return toast.error("اختر الفرع أولاً."); const data = new FormData(event.currentTarget); createDefinition.mutate({ branchId: activeBranchId, name: String(data.get("name")), category: String(data.get("category")) as "sales" | "operations" | "service" | "attendance", unit: String(data.get("unit")) as "currency" | "number" | "percentage" | "minutes", targetValue: Number(data.get("targetValue")), weight: Number(data.get("weight") || 1), measurementPeriod: "monthly", applicableRoles: [String(data.get("applicableRole")) as "manager" | "pharmacist" | "employee"] }); }} className="grid gap-3 sm:grid-cols-4"><label><span className="text-xs font-bold">اسم المؤشر</span><Input name="name" required placeholder="المبيعات الشهرية" className={fieldClass} /></label><label><span className="text-xs font-bold">الفئة</span><select name="category" className={selectClass}><option value="sales">مبيعات</option><option value="operations">تشغيل</option><option value="service">خدمة</option><option value="attendance">حضور</option></select></label><label><span className="text-xs font-bold">الوحدة</span><select name="unit" className={selectClass}><option value="currency">عملة</option><option value="number">رقم</option><option value="percentage">نسبة</option><option value="minutes">دقائق</option></select></label><label><span className="text-xs font-bold">الهدف</span><Input name="targetValue" required type="number" min="0.01" className={fieldClass} /></label><label><span className="text-xs font-bold">ينطبق على</span><select name="applicableRole" className={selectClass}><option value="employee">موظف</option><option value="pharmacist">صيدلاني</option><option value="manager">مدير</option></select></label><Button disabled={createDefinition.isPending} className="sm:w-fit">{createDefinition.isPending ? "جارٍ الحفظ..." : "حفظ المؤشر"}</Button></form></FormCard> : null}{showRecordForm ? <FormCard title="تسجيل نتيجة أداء"><form onSubmit={event => { event.preventDefault(); const data = new FormData(event.currentTarget); record.mutate({ employeeId: Number(data.get("employeeId")), kpiDefinitionId: Number(data.get("kpiDefinitionId")), actualValue: Number(data.get("actualValue")), periodStart: range.from, periodEnd: range.to }); }} className="grid gap-3 sm:grid-cols-4"><label><span className="text-xs font-bold">الموظف</span><select name="employeeId" required className={selectClass}><option value="">اختر الموظف</option>{employeesQuery.data?.map(employee => <option key={employee.id} value={employee.id}>{employee.fullName}</option>)}</select></label><label><span className="text-xs font-bold">المؤشر</span><select name="kpiDefinitionId" required className={selectClass}><option value="">اختر المؤشر</option>{definitions.data?.map(definition => <option key={definition.id} value={definition.id}>{definition.name}</option>)}</select></label><label><span className="text-xs font-bold">القيمة الفعلية</span><Input name="actualValue" type="number" min="0" step="0.01" required className={fieldClass} /></label><div className="flex items-end"><Button disabled={record.isPending}>{record.isPending ? "جارٍ التسجيل..." : "حفظ النتيجة"}</Button></div></form></FormCard> : null}<section className="grid gap-5 xl:grid-cols-2"><Card className="border-[#e1ece6] bg-white"><CardContent className="p-5"><h3 className="text-sm font-extrabold text-[#17344a]">مؤشرات الفرع</h3>{(definitions.data ?? []).length ? <div className="mt-4 divide-y divide-[#edf3ef]">{definitions.data?.map(definition => <div key={definition.id} className="flex items-center justify-between py-3"><div><p className="text-sm font-bold text-[#17344a]">{definition.name}</p><p className="mt-1 text-xs text-slate-500">هدف شهري: {definition.targetValue} · {definition.unit}</p></div><FileBarChart2 className="h-5 w-5 text-[#0f766e]" /></div>)}</div> : <p className="mt-5 text-sm text-slate-500">لا توجد مؤشرات معرفة لهذا الفرع بعد.</p>}</CardContent></Card><Card className="border-[#e1ece6] bg-white"><CardContent className="p-5"><h3 className="text-sm font-extrabold text-[#17344a]">نتائجي هذا الشهر</h3>{(mine.data ?? []).length ? <div className="mt-4 divide-y divide-[#edf3ef]">{mine.data?.map(item => <div key={item.record.id} className="flex items-center justify-between py-3"><div><p className="text-sm font-bold text-[#17344a]">{item.definition.name}</p><p className="mt-1 text-xs text-slate-500">النتيجة: {item.record.actualValue} / {item.record.targetValue}</p></div><Badge className="bg-[#e6f5ef] text-[#0f766e] hover:bg-[#e6f5ef]">{Number(item.record.score).toFixed(0)}٪</Badge></div>)}</div> : <p className="mt-5 text-sm text-slate-500">لم تُسجّل لك نتائج أداء في هذا الشهر.</p>}</CardContent></Card></section></div>;
}

function PayrollModule({ activeBranchId, setActiveBranchId }: { activeBranchId: number; setActiveBranchId: (value: number) => void }) {
  const { user } = useAuth();
  const manager = isManagerRole(user?.role);
  const payrollReviewer = isPayrollRole(user?.role);
  const isHrManager = user?.role === "hr_manager";
  const [showRunForm, setShowRunForm] = useState(false);
  const [showSalaryForm, setShowSalaryForm] = useState(false);
  const branchesQuery = trpc.organization.listBranches.useQuery();
  const employeesQuery = trpc.employees.list.useQuery(activeBranchId ? { branchId: activeBranchId } : undefined, { enabled: manager && activeBranchId > 0 });
  const runs = trpc.payroll.listRuns.useQuery({ branchId: activeBranchId }, { enabled: payrollReviewer && activeBranchId > 0 });
  const configureSalary = trpc.payroll.configureSalary.useMutation({ onSuccess: () => { toast.success("تم حفظ هيكل الراتب."); setShowSalaryForm(false); }, onError: error => toast.error(error.message) });
  const generate = trpc.payroll.generate.useMutation({ onSuccess: data => { toast.success(`تم إنشاء المسير وإضافة ${data.createdItems} بند رواتب.`); setShowRunForm(false); runs.refetch(); }, onError: error => toast.error(error.message) });
  const submitForApproval = trpc.payroll.submitForApproval.useMutation({ onSuccess: () => { toast.success("تم إرسال المسير لاعتماد المدير."); runs.refetch(); }, onError: error => toast.error(error.message) });
  const reviewApproval = trpc.payroll.reviewApproval.useMutation({ onSuccess: data => { toast.success(data.status === "approved" ? "تم اعتماد مسير الرواتب." : data.status === "pending_hr" ? "تمت موافقة المدير وأُحيل المسير للموارد البشرية." : "تم رفض المسير."); runs.refetch(); }, onError: error => toast.error(error.message) });
  const statusLabel: Record<string, string> = { draft: "مسودة", pending_manager: "بانتظار المدير", pending_hr: "بانتظار الموارد البشرية", approved: "معتمد", rejected: "مرفوض", paid: "مدفوع" };
  if (!payrollReviewer) return <><Header module="payroll" actionVisible={false} /><EmptyState icon={HandCoins} title="بيانات الرواتب مخصصة للإدارة" description="تعرض بوابتك الشخصية بيانات الاستحقاقات المعتمدة لك فقط عند تفعيلها من الإدارة." /></>;
  return <div className="space-y-6"><Header module="payroll" action="إنشاء مسير" actionVisible={manager} onAction={manager ? () => setShowRunForm(value => !value) : undefined} /><BranchSelector branches={branchesQuery.data ?? []} value={activeBranchId} onChange={setActiveBranchId} />{manager ? <button onClick={() => setShowSalaryForm(value => !value)} className="text-xs font-bold text-[#0f766e] underline underline-offset-4">{showSalaryForm ? "إخفاء هيكل الراتب" : "ضبط هيكل راتب موظف"}</button> : null}{showSalaryForm ? <FormCard title="هيكل الراتب"><form onSubmit={event => { event.preventDefault(); const data = new FormData(event.currentTarget); configureSalary.mutate({ employeeId: Number(data.get("employeeId")), basicSalary: Number(data.get("basicSalary")), housingAllowance: Number(data.get("housingAllowance") || 0), transportationAllowance: Number(data.get("transportationAllowance") || 0), otherAllowances: Number(data.get("otherAllowances") || 0), maximumKpiBonus: Number(data.get("maximumKpiBonus") || 0), lateDeductionPerMinute: Number(data.get("lateDeductionPerMinute") || 0), effectiveFrom: new Date(String(data.get("effectiveFrom"))) }); }} className="grid gap-3 md:grid-cols-4"><label><span className="text-xs font-bold">الموظف</span><select name="employeeId" className={selectClass} required><option value="">اختر الموظف</option>{employeesQuery.data?.map(employee => <option key={employee.id} value={employee.id}>{employee.fullName}</option>)}</select></label><label><span className="text-xs font-bold">الراتب الأساسي</span><Input name="basicSalary" type="number" min="0" required className={fieldClass} /></label><label><span className="text-xs font-bold">بدل سكن</span><Input name="housingAllowance" type="number" min="0" defaultValue="0" className={fieldClass} /></label><label><span className="text-xs font-bold">بدل انتقال</span><Input name="transportationAllowance" type="number" min="0" defaultValue="0" className={fieldClass} /></label><label><span className="text-xs font-bold">حد مكافأة KPI</span><Input name="maximumKpiBonus" type="number" min="0" defaultValue="0" className={fieldClass} /></label><label><span className="text-xs font-bold">خصم الدقيقة</span><Input name="lateDeductionPerMinute" type="number" min="0" step="0.01" defaultValue="0" className={fieldClass} /></label><label><span className="text-xs font-bold">يسري من</span><Input name="effectiveFrom" type="date" defaultValue={toInputDate(new Date())} required className={fieldClass} /></label><div className="flex items-end"><Button disabled={configureSalary.isPending}>{configureSalary.isPending ? "جارٍ الحفظ..." : "حفظ الهيكل"}</Button></div></form></FormCard> : null}{showRunForm ? <FormCard title="إنشاء مسير رواتب"><form onSubmit={event => { event.preventDefault(); if (!activeBranchId) return toast.error("اختر الفرع أولاً."); const data = new FormData(event.currentTarget); generate.mutate({ branchId: activeBranchId, year: Number(data.get("year")), month: Number(data.get("month")), workingDaysInMonth: Number(data.get("workingDaysInMonth")) }); }} className="grid gap-3 sm:grid-cols-4"><label><span className="text-xs font-bold">السنة</span><Input name="year" type="number" defaultValue={new Date().getFullYear()} className={fieldClass} /></label><label><span className="text-xs font-bold">الشهر</span><Input name="month" type="number" min="1" max="12" defaultValue={new Date().getMonth() + 1} className={fieldClass} /></label><label><span className="text-xs font-bold">أيام العمل</span><Input name="workingDaysInMonth" type="number" min="1" max="31" defaultValue="26" className={fieldClass} /></label><div className="flex items-end"><Button disabled={generate.isPending}>{generate.isPending ? "جارٍ الإنشاء..." : "إنشاء المسير"}</Button></div></form></FormCard> : null}{(runs.data ?? []).length ? <Card className="border-[#e1ece6] bg-white"><CardContent className="divide-y divide-[#edf3ef] p-0">{runs.data?.map(run => { const canSubmit = manager && (run.status === "draft" || run.status === "rejected"); const canReview = (run.status === "pending_manager" && manager) || (run.status === "pending_hr" && (isHrManager || isOwnerRole(user?.role))); return <div key={run.id} className="flex flex-col gap-3 p-5 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-extrabold text-[#17344a]">مسير {run.month}/{run.year}</p><p className="mt-1 text-xs text-slate-500">تاريخ الإنشاء: {formatDate(run.createdAt)}</p></div><div className="flex flex-wrap items-center gap-2"><Badge className={run.status === "approved" || run.status === "paid" ? "bg-[#e6f5ef] text-[#0f766e] hover:bg-[#e6f5ef]" : run.status === "rejected" ? "bg-rose-50 text-rose-700 hover:bg-rose-50" : "bg-[#fff3db] text-[#b87516] hover:bg-[#fff3db]"}>{statusLabel[run.status]}</Badge>{canSubmit ? <Button size="sm" disabled={submitForApproval.isPending} onClick={() => submitForApproval.mutate({ payrollRunId: run.id })}>إرسال للاعتماد</Button> : null}{canReview ? <><Button size="sm" disabled={reviewApproval.isPending} onClick={() => reviewApproval.mutate({ payrollRunId: run.id, decision: "approved" })}>اعتماد</Button><Button size="sm" variant="outline" disabled={reviewApproval.isPending} onClick={() => reviewApproval.mutate({ payrollRunId: run.id, decision: "rejected" })} className="border-rose-200 text-rose-700 hover:bg-rose-50 hover:text-rose-700">رفض</Button></> : null}</div></div>; })}</CardContent></Card> : <EmptyState icon={HandCoins} title="لا توجد مسيرات رواتب" description="اضبط هيكل راتب موظف واحد على الأقل ثم أنشئ مسير الفترة المطلوبة." />}</div>;
}

export default function ModulePage({ module }: { module: Module }) {
  const branches = trpc.organization.listBranches.useQuery();
  const profile = trpc.profile.mine.useQuery();
  const [activeBranchId, setActiveBranchId] = useState(0);
  const resolvedBranchId = useMemo(() => activeBranchId || profile.data?.employee?.branchId || branches.data?.[0]?.id || 0, [activeBranchId, profile.data?.employee?.branchId, branches.data]);
  useEffect(() => { if (!activeBranchId && resolvedBranchId) setActiveBranchId(resolvedBranchId); }, [activeBranchId, resolvedBranchId]);
  if (module === "employees") return <EmployeesModule activeBranchId={resolvedBranchId} setActiveBranchId={setActiveBranchId} />;
  if (module === "attendance") return <AttendanceModule />;
  if (module === "shifts") return <ShiftsModule activeBranchId={resolvedBranchId} setActiveBranchId={setActiveBranchId} />;
  if (module === "leaves") return <LeavesModule activeBranchId={resolvedBranchId} setActiveBranchId={setActiveBranchId} />;
  if (module === "kpis") return <KpisModule activeBranchId={resolvedBranchId} setActiveBranchId={setActiveBranchId} />;
  return <PayrollModule activeBranchId={resolvedBranchId} setActiveBranchId={setActiveBranchId} />;
}
